WITH base AS (SELECT *, COALESCE(rating, 0) AS rating_filled FROM suppliers WHERE supplier_name IS NOT NULL), rating_bucket_summary AS (SELECT CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, city, MAX(rating) - MIN(rating) AS rating_range, MAX(rating_filled) AS max_rating_filled FROM base GROUP BY CASE WHEN rating >= 3.7 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END, city) SELECT * FROM rating_bucket_summary WHERE max_rating_filled >= 42 ORDER BY rating_range ASC, rating_bucket DESC;
